local wezterm = require("wezterm")

-- Palette generated by dux (Linux) from the wallpaper, follows its light/dark mode
local function dux_colors()
	if not wezterm.target_triple:find("linux") then return nil end
	local config_home = os.getenv("XDG_CONFIG_HOME") or (os.getenv("HOME") .. "/.config")
	local path = config_home .. "/wezterm/colors/dank-theme.toml"
	wezterm.add_to_config_reload_watch_list(path)
	local ok, colors = pcall(wezterm.color.load_scheme, path)
	if ok then return colors end
	return nil
end

local function scheme_for_appearance(appearance)
	if appearance:find("Dark") then
		return "Catppuccin Mocha"
	end
	return "Catppuccin Latte"
end

local config = {
	enable_wayland = false,
	font = wezterm.font("JetBrains Mono"),
	font_size = 15,
	window_padding = {
		left = 4,
		right = 4,
		top = 4,
		bottom = 4,
	},
	enable_tab_bar = false,
	window_close_confirmation = "NeverPrompt",
	window_background_opacity = 0.8,
	macos_window_background_blur = 40,
	window_decorations = "INTEGRATED_BUTTONS|RESIZE",
	keys = {
		{ key = "q", mods = "CMD",       action = wezterm.action.CloseCurrentTab({ confirm = false }) },
		{ key = "w", mods = "CMD|SHIFT", action = wezterm.action.CloseCurrentTab({ confirm = false }) },
		{ key = "Enter", mods = "ALT",   action = wezterm.action.DisableDefaultAssignment },
	},
	max_fps = 240,
}

wezterm.on("window-focus-changed", function(window)
	window:set_config_overrides({
		window_background_opacity = window:is_focused() and 0.8 or 0.5,
	})
end)

local colors = dux_colors()
if colors then
	config.colors = colors
else
	config.color_scheme = scheme_for_appearance(wezterm.gui.get_appearance())
end

if wezterm.target_triple:find("darwin") then
	config.window_decorations = "RESIZE"
end

if wezterm.target_triple:find("windows") then
	config.default_domain = "WSL:archlinux"
end

return config
